import { test, expect } from '@playwright/test';

test('mock user list', async ({ page }) => {
  await page.route('**/api/users', async (route) => {
    await route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify([{ id: 1, name: 'Alice' }]),
    });
  });
  await page.goto('/users');
  await expect(page.getByText('Alice')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('block images', async ({ page }) => {
  await page.route('**/*.png', (route) => route.abort());
  await page.route('**/api/data', (route) => route.continue());
  await page.goto('/dashboard');
  await expect(page.getByText('数据加载完成')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test.use({ storageState: 'auth.json' });

test('profile page', async ({ page }) => {
  await page.goto('/profile');
  await expect(page.getByRole('heading', { name: '个人中心' })).toBeVisible();
});

import { test, expect } from '@playwright/test';

test.beforeEach(async ({ request }) => {
  await request.post('/api/todos', { data: { title: '写测试' } });
});

test('seeded todo visible', async ({ page }) => {
  await page.goto('/todos');
  await expect(page.getByText('写测试')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('checkout flow', async ({ page }) => {
  await test.step('加入购物车', async () => {
    await page.goto('/products');
    await page.getByRole('button', { name: '加入购物车' }).click();
  });

  await test.step('查看订单', async () => {
    await page.goto('/cart');
    await expect(page.getByText('1 件商品')).toBeVisible();
  });
});

import { test, expect } from '@playwright/test';

test('dashboard widgets', async ({ page }) => {
  await page.goto('/dashboard');
  await expect.soft(page.getByTestId('sales')).toBeVisible();
  await expect.soft(page.getByTestId('users')).toHaveText('128');
  await expect(page.getByTestId('orders')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('users api', async ({ request }) => {
  const response = await request.get('/api/users');
  expect(response.ok()).toBeTruthy();
  const users = await response.json();
  expect(users).toHaveLength(2);
});

import { test, expect } from '@playwright/test';

test('payment iframe', async ({ page }) => {
  await page.goto('/checkout');
  const frame = page.frameLocator('#payment-frame');
  await frame.getByLabel('卡号').fill('4111111111111111');
  await expect(frame.getByText('支付成功')).toBeVisible();
});

import { test, expect } from '@playwright/test';

test('download report', async ({ page }) => {
  await page.goto('/reports');
  const downloadPromise = page.waitForEvent('download');
  await page.getByRole('button', { name: '导出' }).click();
  const download = await downloadPromise;
  expect(download.suggestedFilename()).toBe('report.csv');
});

